extends Node3D

func _ready() -> void:
	create_column()

func create_column() -> void:
	var pickup_cube_scene = preload("res://commons/scenes/mapobjects/pick_up_cube.tscn")

	# The loop: i counts 0, 1, 2, 3
	for i in range(4):
		var cube_instance = pickup_cube_scene.instantiate()
		cube_instance.name = "Cube_" + str(i)
		# ... position + label in next stages
		add_child(cube_instance)

func apply_grid_config(config: Dictionary) -> void:
	if config.is_empty():
		return
	# Rebuild with new settings
	for child in get_children():
		if not child.owner:
			child.queue_free()
	await get_tree().process_frame

	var count = int(config["count"]) if config.has("count") else 4
	var spacing = float(config["spacing"]) if config.has("spacing") else 1.0
	var label_size = int(config["label_size"]) if config.has("label_size") else 24
	var label_color = Color.from_string(
		config["label_color"], Color(1.0, 0.7, 0.8)
	) if config.has("label_color") else Color(1.0, 0.7, 0.8)

	var pickup_cube_scene = preload("res://commons/scenes/mapobjects/pick_up_cube.tscn")
	for i in range(count):
		var cube = pickup_cube_scene.instantiate()
		cube.position = Vector3(0, 0, i * spacing)
		# ... label as before
		add_child(cube)

func _exit_tree() -> void:
	for child in get_children():
		if not child.owner:
			child.queue_free()

# child.owner is set when loaded from a .tscn scene
# child.owner is null when created in code via .new()
#
# This pattern: 'free what I made, let the scene clean what it loaded.'
# A convention that scales to every artifact in the project.
